**QASM Generálás:**
```zig
pub const QuantumCircuit = struct {
    gates: std.ArrayList(Gate),
    num_qubits: usize,

    pub const Gate = union(enum) {
        h: usize,           // Hadamard on qubit i
        x: usize,           // Pauli-X
        cnot: struct { control: usize, target: usize },
        measure: struct { qubit: usize, classical: usize },
    };

    pub fn toQASM(self: *const QuantumCircuit, allocator: Allocator) ![]u8 {
        var buf = std.ArrayList(u8).init(allocator);
        const writer = buf.writer();

        try writer.print("OPENQASM 2.0;\\n", .{});
        try writer.print("include \\"qelib1.inc\\";\\n", .{});
        try writer.print("qreg q[{d}];\\n", .{self.num_qubits});
        try writer.print("creg c[{d}];\\n", .{self.num_qubits});

        for (self.gates.items) |gate| {
            switch (gate) {
                .h => |i| try writer.print("h q[{d}];\\n", .{i}),
                .x => |i| try writer.print("x q[{d}];\\n", .{i}),
                .cnot => |cn| try writer.print("cx q[{d}],q[{d}];\\n", .{cn.control, cn.target}),
                .measure => |m| try writer.print("measure q[{d}] -> c[{d}];\\n", .{m.qubit, m.classical}),
            }
        }

        return buf.toOwnedSlice();
    }
};
```

