Ez a modul **runtime verifikációs checkek** gyűjteménye, amelyek a Lean4 bizonyításokat **kiegészítik**.

**Típusos Invariánsok:**

```zig
pub fn verifyTensorShapeInvariant(t: *const Tensor) !void {
    var expected_size: usize = 1;
    for (t.shape.dims) |dim| {
        expected_size = try std.math.mul(usize, expected_size, dim);
    }

    if (t.data.len != expected_size) {
        std.debug.print(
            "INVARIANT VIOLATION: Tensor data length {} != expected {}\\n",
            .{t.data.len, expected_size}
        );
        return error.TensorInvariantViolation;
    }
}

pub fn verifyRefCountNonZero(rc: *const RefCount) !void {
    const count = rc.count.load(.SeqCst);
    if (count == 0) {
        std.debug.print("INVARIANT VIOLATION: RefCount is zero\\n", .{});
        return error.RefCountZero;
    }
}
```

**Memória Biztonság:**

```zig
pub fn verifyNoMemoryLeak(allocator: *ArenaAllocator) !void {
    const allocated = allocator.allocated();
    const freed = allocator.freed();

    if (allocated != freed) {
        std.debug.print(
            "MEMORY LEAK DETECTED: allocated={}, freed={}\\n",
            .{allocated, freed}
        );
        return error.MemoryLeak;
    }
}

pub fn verifyBufferBounds(buffer: []const u8, offset: usize, len: usize) !void {
    if (offset + len > buffer.len) {
        std.debug.print(
            "BUFFER OVERFLOW: offset={}, len={}, buffer.len={}\\n",
            .{offset, len, buffer.len}
        );
        return error.BufferOverflow;
    }
}
```

**Numerikus Stabilitás:**

```zig
pub fn verifyNoNaNOrInf(data: []const f32) !void {
    for (data, 0..) |val, i| {
        if (std.math.isNan(val)) {
            std.debug.print("NaN detected at index {}\\n", .{i});
            return error.NaNDetected;
        }
        if (std.math.isInf(val)) {
            std.debug.print("Inf detected at index {}\\n", .{i});
            return error.InfDetected;
        }
    }
}

pub fn verifyGradientNorm(gradient: *const Tensor, max_norm: f32) !void {
    const norm = gradient.norm(2.0);  // L2 norm
    if (norm > max_norm) {
        std.debug.print(
            "GRADIENT EXPLOSION: norm={d:.6}, max={d:.6}\\n",
            .{norm, max_norm}
        );
        return error.GradientExplosion;
    }
}
```

**Használat:**

```zig
pub fn safeForward(layer: *RSFLayer, input: *const Tensor) !Tensor {
    // Pre-conditions
    try verifyTensorShapeInvariant(input);
    try verifyNoNaNOrInf(input.data);

    // Forward pass
    const output = try layer.forward(input);

    // Post-conditions
    try verifyTensorShapeInvariant(&output);
    try verifyNoNaNOrInf(output.data);

    return output;
}
```

