## **VII. ELOSZTOTT RENDSZER ÉS SKÁLÁZÁS**

### **1. Distributed/Distributed_Trainer.zig - Multi-GPU Tanítás**

**Architektúra:**

```zig
pub const DistributedTrainer = struct {
    world_size: usize,       // Total GPU count
    rank: usize,             // This GPU's ID
    model: ModelFormat,
    optimizer: SFDOptimizer,
    communicator: *NCCLCommunicator,
    allocator: Allocator,

    pub fn init(
        allocator: Allocator,
        rank: usize,
        world_size: usize,
        model_config: ModelConfig
    ) !DistributedTrainer {
        // Initialize NCCL (NVIDIA Collective Communications Library)
        var comm = try NCCLCommunicator.init(rank, world_size);

        // Create model replica on this GPU
        var model = try ModelFormat.init(allocator, model_config);

        // Broadcast initial weights from rank 0
        if (rank == 0) {
            try comm.broadcast(model.getAllWeights(), 0);
        } else {
            const weights = try comm.broadcast(null, 0);
            try model.setAllWeights(weights);
        }

        return .{
            .world_size = world_size,
            .rank = rank,
            .model = model,
            .optimizer = try SFDOptimizer.init(allocator),
            .communicator = comm,
            .allocator = allocator,
        };
    }
};
```

**Data Parallel Training:**

```zig
pub fn trainEpoch(
    self: *DistributedTrainer,
    dataset: *Dataset,
    batch_size: usize
) !f32 {
    var total_loss: f32 = 0.0;
    var num_batches: usize = 0;

    // Each GPU processes a shard of the data
    const shard_size = dataset.size / self.world_size;
    const shard_start = self.rank * shard_size;
    const shard_end = if (self.rank == self.world_size - 1)
        dataset.size
    else
        (self.rank + 1) * shard_size;

    var offset: usize = shard_start;
    while (offset < shard_end) : (offset += batch_size) {
        const actual_batch_size = @min(batch_size, shard_end - offset);

        // 1. Forward pass (local to this GPU)
        const batch = try dataset.getBatch(offset, actual_batch_size);
        defer batch.deinit();

        const predictions = try self.model.forward(&batch.inputs);
        defer predictions.deinit();

        const loss = try computeLoss(&predictions, &batch.targets);
        total_loss += loss;
        num_batches += 1;

        // 2. Backward pass (compute local gradients)
        const gradients = try self.model.backward(&predictions, &batch.targets);
        defer gradients.deinit();

        // 3. **AllReduce gradients (synchronize across GPUs)**
        try self.communicator.allReduceSum(&gradients);

        // Average gradients
        try scaleInPlace(&gradients, 1.0 / @as(f32, @floatFromInt(self.world_size)));

        // 4. Update weights (now all GPUs have same gradients)
        try self.optimizer.step(&gradients);
    }

    // AllReduce total loss for logging
    var global_loss = total_loss;
    try self.communicator.allReduceSum(&global_loss);

    return global_loss / @as(f32, @floatFromInt(num_batches * self.world_size));
}
```

**NCCL Bindings:**

```zig
pub const NCCLCommunicator = struct {
    comm: nccl.ncclComm_t,
    stream: cuda.cudaStream_t,
    rank: usize,
    world_size: usize,

    pub fn allReduceSum(self: *NCCLCommunicator, tensor: *Tensor) !void {
        const count = tensor.data.len;
        const datatype = nccl.ncclFloat32;
        const op = nccl.ncclSum;

        try checkNCCLError(nccl.ncclAllReduce(
            @ptrCast(tensor.data.ptr),  // sendbuf
            @ptrCast(tensor.data.ptr),  // recvbuf (in-place)
            count,
            datatype,
            op,
            self.comm,
            self.stream
        ));

        try checkCudaError(cuda.cudaStreamSynchronize(self.stream));
    }

    pub fn broadcast(self: *NCCLCommunicator, data: ?*Tensor, root: usize) !?*Tensor {
        if (self.rank == root) {
            // Root sends
            const tensor = data.?;
            try checkNCCLError(nccl.ncclBroadcast(
                @ptrCast(tensor.data.ptr),
                @ptrCast(tensor.data.ptr),
                tensor.data.len,
                nccl.ncclFloat32,
                root,
                self.comm,
                self.stream
            ));
            return tensor;
        } else {
            // Non-root receives
            var recv_size: usize = 0;
            try checkNCCLError(nccl.ncclBroadcast(
                @ptrCast(&recv_size),
                @ptrCast(&recv_size),
                1,
                nccl.ncclUint64,
                root,
                self.comm,
                self.stream
            ));

            var tensor = try Tensor.init(self.allocator, &.{recv_size});
            try checkNCCLError(nccl.ncclBroadcast(
                null,
                @ptrCast(tensor.data.ptr),
                recv_size,
                nccl.ncclFloat32,
                root,
                self.comm,
                self.stream
            ));

            return tensor;
        }
    }
};
```

**Teljesítmény:**

- **Linear scaling** (2x GPU = 2x throughput)
- **Gradient AllReduce** typically < 5% overhead (with fast interconnects like NVLink)
- **Supports 100s of GPUs** (NCCL optimized for large clusters)

