#### **c) Inference Endpoint**

```zig
fn handleInference(
    self: *InferenceServer,
    stream: net.Stream,
    body: []const u8,
    allocator: Allocator
) !void {
    if (self.model == null or self.model.?.mgt == null) {
        try self.sendError(stream, "Model not loaded", 503);
        return;
    }

    const start_time = std.time.milliTimestamp();

    // Parse request
    var request = InferenceRequest.fromJson(allocator, body) catch {
        try self.sendError(stream, "Invalid JSON request", 400);
        return;
    };
    defer request.deinit(allocator);

    // Tokenize
    var tokens = std.ArrayList(u32).init(allocator);
    defer tokens.deinit();
    try self.model.?.mgt.?.encode(request.text, &tokens);

    // Truncate to max_tokens
    const max_tokens = request.max_tokens orelse tokens.items.len;
    const final_tokens = tokens.items[0..@min(tokens.items.len, max_tokens)];

    // Generate embeddings (if requested)
    var embeddings: ?[]f32 = null;
    if (request.return_embeddings and self.model.?.rsf != null) {
        const dim = self.model.?.rsf.?.ctrl.?.dim;

        var input_tensor = try Tensor.init(allocator, &.{1, dim * 2});
        defer input_tensor.deinit();

        // Convert tokens to float input
        for (input_tensor.data, 0..) |*val, i| {
            val.* = if (i < final_tokens.len)
                @as(f32, @floatFromInt(final_tokens[i])) / 1000.0
            else
                0.0;
        }

        // Forward pass
        try self.model.?.rsf.?.forward(&input_tensor);

        // Extract embeddings
        embeddings = try allocator.alloc(f32, @min(dim, 128));
        @memcpy(embeddings.?, input_tensor.data[0..embeddings.?.len]);
    }

    // Update SSI index (for future retrievals)
    self.inference_mutex.lock();
    defer self.inference_mutex.unlock();

    if (self.ssi) |*ssi_idx| {
        const is_anchor = (self.request_count % 10 == 0);
        try ssi_idx.addSequence(final_tokens, self.request_count, is_anchor);

        // Rank similar sequences
        if (self.ranker) |*rnk| {
            const candidates = try ssi_idx.retrieveTopK(final_tokens, 3, allocator);
            defer allocator.free(candidates);
            try rnk.rankCandidatesWithQuery(candidates, final_tokens, ssi_idx, allocator);
        }
    }
    self.request_count += 1;

    const end_time = std.time.milliTimestamp();
    const processing_time = @as(f64, @floatFromInt(end_time - start_time));

    // Build response
    var response = InferenceResponse{
        .tokens = try allocator.dupe(u32, final_tokens),
        .embeddings = embeddings,
        .processing_time_ms = processing_time,
    };
    defer response.deinit(allocator);

    const json = try response.toJson(allocator);
    defer allocator.free(json);

    // Send HTTP response
    var response_buf = std.ArrayList(u8).init(allocator);
    defer response_buf.deinit();
    const writer = response_buf.writer();

    try writer.writeAll("HTTP/1.1 200 OK\\r\\n");
    try writer.writeAll("Content-Type: application/json\\r\\n");
    try writer.writeAll("Access-Control-Allow-Origin: *\\r\\n");
    try writer.print("Content-Length: {d}\\r\\n", .{json.len});
    try writer.writeAll("\\r\\n");
    try writer.writeAll(json);

    _ = try stream.write(response_buf.items);
}
```

