    const run_cmd = b.addRunArtifact(main_exe);
    const run_step = b.step("run", "Run JAIDE");
    run_step.dependOn(&run_cmd.step);

    const run_server_cmd = b.addRunArtifact(inference_exe);
    const run_server_step = b.step("run-server", "Run inference server");
    run_server_step.dependOn(&run_server_cmd.step);

    // Tests
    const tensor_tests = b.addTest(.{
        .root_source_file = .{ .path = "src/core/tensor.zig" },
        .target = target,
        .optimize = optimize,
    });
    const test_step = b.step("test-tensor", "Run tensor tests");
    test_step.dependOn(&b.addRunArtifact(tensor_tests).step);
}
```

**Build Commands:**

```bash
# Development build
zig build

# Release (optimized)
zig build -Doptimize=ReleaseFast

# Run main executable
zig build run

# Run inference server
zig build run-server -- --port 8080

# Run tests
zig build test-tensor
zig build test-memory
```

